<style>
:root{font-family:Inter,Arial,sans-serif;--navy:#1e315b;--dark:#132137;--red:#ce122d;--light:#f7f9fc;--muted:#68758a;--line:#e4e9f1;--surface:#fff;--shadow:0 18px 45px rgba(19,33,55,.09)}*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;color:var(--dark);background:#fff}a{text-decoration:none;color:inherit}img{max-width:100%}.wrap{width:min(1240px,92%);margin:auto}.top{background:rgba(255,255,255,.96);border-bottom:1px solid var(--line);position:sticky;top:0;z-index:50;backdrop-filter:blur(12px)}.nav{display:flex;align-items:center;gap:18px;min-height:82px}.logo{width:122px;height:64px;object-fit:contain;margin-right:auto}.nav-links{display:flex;align-items:center;gap:18px}.nav-link{font-size:14px;font-weight:700;color:#47566d}.nav-link:hover{color:var(--red)}.nav-actions{display:flex;align-items:center;gap:8px}.btn{display:inline-flex;justify-content:center;align-items:center;min-height:44px;padding:11px 17px;border-radius:10px;background:var(--navy);color:#fff;font-weight:800;border:1px solid transparent}.btn.red{background:var(--red)}.btn.light{background:#fff;color:var(--navy);border-color:#dce3ec}.lang{font-size:13px;font-weight:900;color:var(--navy);border:1px solid var(--line);padding:10px 12px;border-radius:9px;background:#fff}.menu-toggle{display:none;border:0;background:var(--navy);color:#fff;width:44px;height:44px;border-radius:10px;font-size:22px}.mobile-menu{display:none;padding:0 0 14px}.mobile-menu.open{display:grid;gap:8px}.mobile-menu a{padding:12px 14px;background:#f7f9fc;border-radius:9px;font-weight:700;color:var(--navy)}.hero{position:relative;overflow:hidden;padding:86px 0 64px;background:radial-gradient(circle at 90% 10%,rgba(206,18,45,.08),transparent 28%),linear-gradient(135deg,#fff 0%,#f8fafc 62%,#eef3f9 100%)}.hero-grid{display:grid;grid-template-columns:1.15fr .85fr;gap:58px;align-items:center}.eyebrow{display:inline-flex;align-items:center;gap:8px;color:var(--red);font-size:13px;font-weight:900;letter-spacing:.05em}.eyebrow:before{content:"";width:34px;height:3px;border-radius:999px;background:var(--red)}.hero h1{font-size:clamp(38px,4.8vw,62px);line-height:1.12;color:var(--navy);margin:16px 0 18px}.hero p,.lead{color:#5e6d82;line-height:1.9}.hero p{font-size:18px;max-width:720px}.actions{display:flex;gap:10px;flex-wrap:wrap;margin-top:26px}.hero-visual{background:#fff;border:1px solid rgba(30,49,91,.08);border-radius:28px;padding:28px;box-shadow:var(--shadow)}.hero-logo{width:100%;height:330px;object-fit:contain}.trust-strip{margin-top:-18px}.trust-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;background:#fff;border:1px solid var(--line);border-radius:18px;padding:12px;box-shadow:0 16px 35px rgba(19,33,55,.08)}.trust-item{padding:14px 16px;border-right:1px solid #edf1f6}.trust-item:last-child{border-right:0}.trust-item strong{display:block;color:var(--navy);font-size:17px;margin-bottom:5px}.trust-item span{color:var(--muted);font-size:12px;line-height:1.6}.section{padding:74px 0}.section-head{margin-bottom:28px;max-width:800px}.kicker{color:var(--red);font-size:13px;font-weight:900;margin-bottom:8px}h2{color:var(--navy);font-size:clamp(28px,3vw,38px);margin:0 0 12px}.alt{background:var(--light)}.about-grid{display:grid;grid-template-columns:1.1fr .9fr;gap:30px}.about-panel{background:linear-gradient(145deg,var(--dark),var(--navy));color:#fff;border-radius:20px;padding:26px}.about-panel p{color:#d8e0eb;line-height:1.8}.about-points{display:grid;grid-template-columns:1fr 1fr;gap:12px}.point,.card,.step{background:#fff;border:1px solid var(--line);border-radius:14px;padding:18px}.point b,.card b,.step b{display:block;color:var(--navy);margin-bottom:7px}.point span,.card p,.step p{color:var(--muted);line-height:1.7;margin:0}.cards{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}.service-no{display:inline-flex;width:38px;height:38px;align-items:center;justify-content:center;border-radius:10px;background:#eef3fa;color:var(--navy);font-weight:900;margin-bottom:14px}.process{display:grid;grid-template-columns:repeat(4,1fr);gap:14px}.step-num{display:inline-flex;width:34px;height:34px;border-radius:50%;align-items:center;justify-content:center;background:var(--red);color:#fff;font-weight:900;margin-bottom:12px}.cta{padding:38px;border-radius:22px;background:linear-gradient(135deg,var(--dark),var(--navy));color:#fff;display:flex;justify-content:space-between;align-items:center;gap:26px}.cta h2{color:#fff}.cta p{color:#d6dfeb;max-width:720px;line-height:1.8}.footer{background:#0f1a2b;color:#cbd5e1;padding:32px 0}.foot{display:flex;justify-content:space-between;gap:18px;align-items:center}.foot-logo{width:82px;height:48px;object-fit:contain;background:#fff;border-radius:8px;padding:5px}@media(max-width:1050px){.nav-links{display:none}.menu-toggle{display:inline-flex;align-items:center;justify-content:center}.hero-grid,.about-grid{grid-template-columns:1fr}.trust-grid{grid-template-columns:repeat(2,1fr)}.cards{grid-template-columns:repeat(2,1fr)}.process{grid-template-columns:repeat(2,1fr)}}@media(max-width:720px){.nav{min-height:70px}.logo{width:100px;height:52px}.nav-actions .btn:not(.red){display:none}.hero{padding:54px 0 44px}.hero h1{font-size:36px}.hero-logo{height:230px}.trust-strip{margin-top:0;padding-top:14px}.section{padding:54px 0}.about-points,.cards,.process{grid-template-columns:1fr}.cta{flex-direction:column;align-items:flex-start}.foot{flex-direction:column;align-items:flex-start}}@media(max-width:460px){.nav-actions .btn.red{display:none}.hero h1{font-size:31px}.actions{display:grid}.actions .btn{width:100%}.trust-grid{grid-template-columns:1fr}.hero-logo{height:190px}}
